local B=require('biology');local G=require('genome');local V=require('vessels');local M=require('desktop_model');local F=require('physical_cells');local D=require('workshop_docking');local W=require('cell_workshop');local T=require('desktop_samples');local S=require('persistence');local Tests={}
local function state() local s=B.new(925);V.ensure(s);M.ensure(s);F.ensure(s);return s end
local function setup(category)
 local s=state();local _,_,input=F.buy(s,category or 1);V.add(s,4,true);local output=s.vessels[#s.vessels]
 local station=M.add(s,'workstation','workstation','laboratory',100,80);station.config.expanded=true;station.w=1050;station.h=640
 local source=M.add(s,'vial',input.id);local dest=M.add(s,'vial',output.id);assert(D.attach(s,station.id,source.id,'input'));assert(D.attach(s,station.id,dest.id,'output'));return s,station,input,output,source,dest
end
function Tests.run()
 local lines,failed,groups={},0,0;local function test(name,fn) groups=groups+1; local ok,why=xpcall(fn,debug.traceback);lines[#lines+1]=(ok and 'PASS ' or 'FAIL ')..name;if not ok then failed=failed+1;lines[#lines+1]=why end end
 test('New physical-stock session starts with zero ordinary, blank or frozen cells',function() local s=state();assert(#s.cells==0 and #s.frozen==0 and #s.gametes==0 and s.desktop.blankCells==0);for _,v in ipairs(s.vessels) do assert(V.count(v)==0) end end)
 test('Each ordinary and blank purchase costs one credit and supplies exactly one cell in its own vial',function() local s=state();local initial=s.credits;for _,category in ipairs({1,2,3,4,5,6,7,'blank'}) do local before=#s.vessels;local ok,_,v=F.buy(s,category);assert(ok and #s.vessels==before+1 and V.count(v)==1 and v.kind==4 and #s.cells==0);assert(category~='blank' or v.contents[1].cell.sampleKind=='blank') end;assert(s.credits==initial-8) end)
 test('Insufficient-credit purchase leaves money, IDs and stock unchanged',function() local s=state();s.credits=0;local before=S.encode(s);assert(not F.buy(s,1));assert(S.encode(s)==before) end)
 test('Separately purchased containers are empty',function() local s=state();local credits=s.credits;assert(V.add(s,4));assert(V.count(s.vessels[#s.vessels])==0 and s.credits==credits-8) end)
 test('One-credit supplied vials cannot be immediately resold for a profit or withdrawn into new free packaging',function() local s=state();local initial=s.credits;local _,_,v=F.buy(s,1);assert(not V.withdraw(s,#s.vessels));assert(V.sellVessel(s,#s.vessels));assert(s.credits<=initial) end)
 test('Docking is exclusive ID-based attachment and never copies biological contents',function() local s,o,input,output,source=setup();local before=S.encode(s.vessels);local other=M.add(s,'workstation','second');assert(not D.attach(s,other.id,source.id,'input'));assert(not D.attach(s,o.id,source.id,'output'));assert(S.encode(s.vessels)==before);assert(D.container(s,o.id,'input')==input and D.container(s,o.id,'output')==output) end)
 test('Empty input and populated output are rejected without replacing another attachment',function() local s,o,input,output,source,dest=setup();D.detach(s,dest.id);assert(not D.attach(s,o.id,dest.id,'input'));assert(not D.attach(s,o.id,source.id,'output'));assert(o.config.docks.input==source.id and not o.config.docks.output) end)
 test('DNA extraction archives exact DNA, retains source and writes only to this workshop terminal',function() local s,o,input=setup();local before=S.encode(s.vessels);local genome=G.hash(input.contents[1].cell.genome);assert(W.extract(s,o.id));assert(S.encode(s.vessels)==before and #s.materials==1 and G.hash(s.materials[1].genome)==genome and #s.cells==0);assert(o.config.terminal[1]:find('retained')) end)
 test('DNA extraction works without an output container because its result is an archive record',function() local s,o,_,_,_,dest=setup();D.detach(s,dest.id);assert(W.extract(s,o.id) and #s.materials==1) end)
 test('Blank/haploid inputs cannot be used as ordinary DNA extraction sources',function() local s,o,input=setup('blank');assert(not W.extract(s,o.id));assert(#s.materials==0 and V.count(input)==1) end)
 test('Installation consumes exactly one physical blank and outputs one cell with exact selected DNA',function() local s,o,input,output=setup('blank');local genome=G.new(G.rng(123));s.materials={{id=700,name='Test genome',genome=genome}};o.config.genomeId=700;assert(W.install(s,o.id));assert(V.count(input)==0 and V.count(output)==1 and #s.cells==0 and s.desktop.blankCells==0);assert(G.hash(output.contents[1].cell.genome)==G.hash(genome) and output.contents[1].cell.developmentalCell) end)
 test('Missing genome/output, wrong input and closed/frozen containers cannot consume cells',function() local s,o,input,output,_,dest=setup('blank');local before=S.encode(s.vessels);assert(not W.install(s,o.id));assert(S.encode(s.vessels)==before);s.materials={{id=1,genome=G.new(G.rng(5))}};o.config.genomeId=1;output.closed=true;assert(not W.install(s,o.id));assert(V.count(input)==1 and V.count(output)==0);output.closed=false;D.detach(s,dest.id);assert(not W.install(s,o.id));assert(V.count(input)==1) end)
 test('Egg preparation consumes one stem and creates one physical precursor linked to actual haploid genetics',function() local s,o,input,output=setup();assert(W.precursor(s,o.id,'Egg'));assert(V.count(input)==0 and V.count(output)==1 and #s.gametes==1 and #s.cells==0);local c=output.contents[1].cell;assert(c.sampleKind=='gamete' and c.gameteId==s.gametes[1].id and s.gametes[1].alleles and c.gameteKind=='Egg') end)
 test('Sperm preparation and eight-minute maturation use the real PC-rate biological update',function() local s,o,_,output=setup();assert(W.precursor(s,o.id,'Sperm'));B.update(s,2);F.ensure(s);assert(math.abs(s.gametes[1].progress-.25)<1e-6 and output.contents[1].cell.gameteProgress==s.gametes[1].progress);B.update(s,6);F.ensure(s);assert(s.gametes[1].progress==1) end)
 test('Unsuitable cell type and poor viability reject preparation without creating or consuming stock',function() local s,o,input,output=setup(2);assert(not W.precursor(s,o.id,'Egg'));assert(V.count(input)==1 and V.count(output)==0 and #s.gametes==0);input.contents[1].cell.type=1;input.contents[1].cell.viability=.2;assert(not W.precursor(s,o.id,'Egg'));assert(V.count(input)==1) end)
 test('Blank cells and haploid precursors cannot multiply as ordinary cultures',function() local s,o,input,output=setup('blank');input.kind=1;B.update(s,60);assert(V.count(input)==1 and V.growthInfo(input).status~='Growing');input.contents[1].cell.sampleKind=nil;assert(W.precursor(s,o.id,'Egg'));output.kind=1;B.update(s,60);assert(V.count(output)==1 and V.growthInfo(output).status~='Growing') end)
 test('Freeze loaded dropper contents conserves quantity and leaves the physical dropper usable',function() local s,_,input=setup();assert(T.collect(s,input.id));local hash=G.hash(s.desktop.pipette.sample.cell.genome);assert(T.freezeLoaded(s));assert(not s.desktop.pipette.sample and #s.frozen==1 and V.count(input)==0 and #s.cells==0);assert(G.hash(s.frozen[1].genome)==hash);assert(T.clean(s)) end)
 test('Frozen storage stops gamete maturation; retrieval resumes in the chosen container',function() local s,o,_,output=setup();assert(W.precursor(s,o.id,'Egg'));B.update(s,1);F.ensure(s);assert(T.collect(s,output.id));assert(T.freezeLoaded(s));local progress=s.gametes[1].progress;B.update(s,10);assert(s.gametes[1].progress==progress);assert(T.restoreFrozen(s,s.frozen[1].id,output.id));B.update(s,1);F.ensure(s);assert(s.gametes[1].progress>progress and #s.frozen==0 and V.count(output)==1) end)
 test('Rejected frozen retrieval preserves the stored sample and target contents',function() local s,_,input,output=setup();assert(T.collect(s,input.id));assert(T.freezeLoaded(s));local before=S.encode(s.frozen);output.closed=true;assert(not T.restoreFrozen(s,s.frozen[1].id,output.id));assert(S.encode(s.frozen)==before and V.count(output)==0);output.closed=false;output.contents={{cell=B.cell(s,2),count=1}};assert(not T.restoreFrozen(s,s.frozen[1].id,output.id));assert(S.encode(s.frozen)==before and V.count(output)==1) end)
 test('Frozen packet and attached container IDs survive save/load and restore without duplicates',function() local s,o,input,output=setup();assert(T.collect(s,input.id));assert(T.freezeLoaded(s));local restored=assert(S.decode('return '..S.encode(s),B));F.ensure(restored);assert(D.container(restored,o.id,'output').id==output.id);assert(T.restoreFrozen(restored,restored.frozen[1].id,output.id));assert(#restored.frozen==0 and #restored.cells==0 and V.count(restored.vessels[#restored.vessels])==1) end)
 test('Existing loose and blank stock migrates once into physical vials without loss',function() local s=B.new(27);V.ensure(s);M.ensure(s);s.cells={B.cell(s,1),B.cell(s,2)};local ids={s.cells[1].id,s.cells[2].id};s.desktop.blankCells=3;F.ensure(s);local found={},0;local count=0;for _,v in ipairs(s.vessels) do for _,b in ipairs(v.contents) do count=count+b.count;found[b.cell.id]=true end end;assert(#s.cells==0 and count==5 and found[ids[1]] and found[ids[2]] and s.desktop.blankCells==0);local n=#s.vessels;F.ensure(s);assert(#s.vessels==n) end)
 test('Existing gamete-bank records gain physical vials without changing haploid alleles',function() local s=B.new(31);V.ensure(s);M.ensure(s);s.cells={B.cell(s,1)};assert(B.precursor(s,1,'Egg'));local h=s.gametes[1];local alleles=S.encode(h.alleles);F.ensure(s);assert(h.physical and h.containerId and S.encode(h.alleles)==alleles);local found=false;for _,v in ipairs(s.vessels) do if v.contents[1] and v.contents[1].cell.gameteId==h.id then found=true end end;assert(found) end)
 test('Physical fertilization consumes the actual egg/sperm records and removes emptied specimen vessels',function() local s,o,input,output=setup();assert(W.precursor(s,o.id,'Egg'));local egg=s.gametes[1];D.detach(s,o.config.docks.input);D.detach(s,o.config.docks.output);input.contents={{cell=B.cell(s,1),count=1}};V.add(s,4,true);local spermVial=s.vessels[#s.vessels];local inObj=M.add(s,'vial',input.id);local outObj=M.add(s,'vial',spermVial.id);assert(D.attach(s,o.id,inObj.id,'input'));assert(D.attach(s,o.id,outObj.id,'output'));assert(W.precursor(s,o.id,'Sperm'));local sperm=s.gametes[2];B.update(s,8);assert(B.fertilize(s,egg.id,sperm.id));F.ensure(s);assert(#s.gametes==0 and V.count(output)==0 and V.count(spermVial)==0 and #s.eggs==1) end)
 test('Installed cell begins existing incubation from its own container and is consumed once',function() local s,o,input,output=setup('blank');s.materials={{id=900,genome=G.new(G.rng(20365841))}};o.config.genomeId=900;assert(W.install(s,o.id));assert(F.beginDevelopment(s,output.id));assert(#s.eggs==1 and V.count(output)==0 and not F.beginDevelopment(s,output.id)) end)
 test('Docked group movement and negative-coordinate monitor layout preserve fixed attachment identities',function() local s,o,input,output,source,dest=setup();local monitors={{id='left',x=-1920,y=0,w=1920,h=1080,dpi=96},{id='right',x=0,y=0,w=1920,h=1080,dpi=96}};o.x=-1700;o.y=80;D.layout(s,o,monitors);local x=source.x;local before=S.encode(s.vessels);o.x=o.x+100;D.layout(s,o,monitors);assert(source.x==x+100 and source.config.workshop==o.id and dest.config.workshop==o.id and S.encode(s.vessels)==before) end)
 test('Direct workshop UI and taskbar purchase/frozen menus expose only the agreed functions',function()
  local Host=require('desktop_host');local N=require('native_windows');local C=require('desktop_controls');local Art=require('desktop_art');local s,o,input,output,source,dest=setup();Host.monitors={{id='primary',x=0,y=0,w=1920,h=1080,dpi=96,primary=true}};Host.context={getState=function() return s end,msg=function() end};Host.testing=true;local sync=Host.sync;Host.sync=function() F.ensure(s) end
  local canvas=love.graphics.newCanvas(1080,690);love.graphics.push('all');love.graphics.setCanvas(canvas);love.graphics.clear(.02,.04,.05);love.graphics.translate(15,15);C.draw(s,o);local hits={};for _,hit in ipairs(C.hits[o.id]) do hits[hit.id]=hit.fn;assert(not hit.id:find('Feed') and not hit.id:find('wild') and not hit.id:find('Withdraw') and not hit.id:find('Buy')) end;assert(hits['Extract DNA to genome archive'] and hits['Install selected DNA / uses 1 blank cell'] and hits['Prepare egg / uses 1 stem cell']);hits['Extract DNA to genome archive']();love.graphics.clear(.02,.04,.05);C.draw(s,o);D.layout(s,o,Host.monitors);for _,object in ipairs({source,dest}) do love.graphics.push();love.graphics.translate(object.x-o.x,object.y-o.y);Art.draw(s,object);love.graphics.pop() end;love.graphics.setCanvas();local data=canvas:newImageData():encode('png');local root=love.filesystem.isFused() and love.filesystem.getSourceBaseDirectory() or love.filesystem.getSource();local file=assert(io.open(root..'/workshop-preview.png','wb'));file:write(data:getString());file:close();love.graphics.pop()
  local menu=N.menu;local seenBuy,seenFrozen=false,false;N.menu=function(items) for _,item in ipairs(items) do if item.label=='Buy supplies...' then seenBuy=true end;if item.label=='Retrieve frozen cells...' then seenFrozen=true end end;return nil end;Host.tray();assert(seenBuy and seenFrozen);local count=0;N.menu=function(items) count=#items;assert(items[1].label:find('1 credit'));return items[1].action end;local credits=s.credits;require('desktop_supply_menus').buy(s);assert(count>=13 and s.credits==credits-1)
  N.menu=menu;Host.sync=sync;Host.context=nil;Host.testing=false
 end)
 lines[#lines+1]=string.format('%d groups executed; %d failures.',groups,failed);local result=table.concat(lines,'\n');local root=love.filesystem.isFused() and love.filesystem.getSourceBaseDirectory() or love.filesystem.getSource();local f=assert(io.open(root..'/workshop-test-results.txt','w'));f:write(result);f:close();assert(failed==0,result);return result
end
return Tests
